import sys
input = sys.stdin.read().split()

index = 0
T = int(input[index])
index += 1
results = []

for _ in range(T):
    N = int(input[index])
    K = int(input[index + 1])
    index += 2
    A = list(map(int, input[index:index + N]))
    index += N

    if N == 1:
        if A[0] == -1:
            results.append("YES\n1")
        else:
            results.append("YES\n" + str(A[0]))
        continue

    possible = True
    for i in range(N):
        if A[i] == -1:
            if i == 0:
                A[i] = 1 if A[i + 1] != 1 else 2
            elif i == N - 1:
                A[i] = 1 if A[i - 1] != 1 else 2
            else:
                for j in range(1, K + 1):
                    if j != A[i - 1] and j != A[i + 1]:
                        A[i] = j
                        break
        else:
            if i > 0 and A[i] == A[i - 1]:
                possible = False
                break

    if possible:
        results.append("YES\n" + " ".join(map(str, A)))
    else:
        results.append("NO")

print("\n".join(results))
